#ifndef AST_H
#define AST_H

#include <stddef.h>
#include "decimal.h"
#include "complex.h"

// ============================================================================
// File: ast.h
// Purpose: Definitions for the Abstract Syntax Tree (AST) nodes and Value system.
// Role:
//   Defines the tree structure generated by the recursive-descent parser.
//   Decouples syntax analysis from semantic evaluation, allowing post-order
//   tree walks to evaluate mathematical expressions with arbitrary precision.
// ============================================================================

// Forward declaration of the AST node structure
typedef struct ExprNode ExprNode;

// Discriminator for what kind of expression an AST node represents
typedef enum {
    NODE_NUMBER, // Numeric constant literal (integer, decimal, or scientific notation)
    NODE_VAR,    // Variable identifier lookup (e.g., 'x', 'ans', 'pi', 'e')
    NODE_UNARY,  // Unary prefix/postfix operation (+a, -a, a!)
    NODE_BINARY, // Binary infix operation (a + b, a - b, a * b, a / b, a % b, a ^ b)
    NODE_CALL    // Function call invocation with argument list (e.g., sin(x), gcd(a, b))
} NodeType;

// Operational codes for both binary and unary operators
typedef enum {
    OP_ADD,  // Binary addition (+)
    OP_SUB,  // Binary subtraction (-)
    OP_MUL,  // Binary multiplication (*)
    OP_DIV,  // Binary division (/)
    OP_MOD,  // Binary modulo (%)
    OP_POW,  // Binary exponentiation (^)
    OP_NEG,  // Unary arithmetic negation (-x)
    OP_POS,  // Unary positive sign (+x, identity)
    OP_FACT  // Unary postfix factorial (x!)
} OpCode;

// Discriminator tag for polymorphic calculation values
typedef enum {
    VAL_INT,     // Arbitrary-precision integer (BigInteger)
    VAL_DEC,     // Arbitrary-precision decimal (BigDecimal: significand + scale)
    VAL_COMPLEX  // Complex number (Complex: real + imag BigDecimal components)
} ValueType;

// Tagged union representing any valid mathematical value in the calculator
typedef struct {
    ValueType type; // Active type discriminator (VAL_INT, VAL_DEC, VAL_COMPLEX)
    union {
        BigInteger i; // Base-10^9 limb array integer
        BigDecimal d; // Scaled arbitrary-precision decimal
        Complex    c; // Complex number with real and imaginary decimals
    } as;
} Value;

// Structure representing a single node in the Abstract Syntax Tree (AST)
struct ExprNode {
    NodeType type; // Kind of node (number, variable, binary, unary, call)
    size_t   pos;  // 1-indexed source column position in user input for error reporting

    union {
        Value number;   // Value payload for NODE_NUMBER
        char *var_name; // Heap-allocated variable name string for NODE_VAR

        // Child operands and operator for binary operations (NODE_BINARY)
        struct {
            OpCode    op;    // Binary operator (+, -, *, /, %, ^)
            ExprNode *left;  // Pointer to left-hand operand sub-tree
            ExprNode *right; // Pointer to right-hand operand sub-tree
        } bin;

        // Child operand and operator for unary operations (NODE_UNARY)
        struct {
            OpCode    op;      // Unary operator (OP_NEG, OP_POS, OP_FACT)
            ExprNode *operand; // Pointer to target operand sub-tree
        } un;

        // Function call parameters and arguments array (NODE_CALL)
        struct {
            int        fn_id; // Function lookup index matching FUNCTIONS table
            size_t     argc;  // Count of arguments passed to function
            ExprNode **args;  // Dynamically allocated array of pointers to argument sub-trees
        } call;
    } as;
};

// ----------------------------------------------------------------------------
// AST Node Constructors & Destructor
// ----------------------------------------------------------------------------

// Creates a numeric constant AST node by parsing an integer or decimal string
ExprNode *node_new_number(const char *str, size_t pos);

// Creates a variable reference AST node holding the identifier name
ExprNode *node_new_var(const char *name, size_t pos);

// Creates a binary operator AST node linking left and right child sub-trees
ExprNode *node_new_binary(OpCode op, ExprNode *left, ExprNode *right, size_t pos);

// Creates a unary operator AST node wrapping a single operand sub-tree
ExprNode *node_new_unary(OpCode op, ExprNode *operand, size_t pos);

// Creates a function call AST node containing an array of argument sub-trees
ExprNode *node_new_call(int fn_id, ExprNode **args, size_t argc, size_t pos);

// Recursively walks and deallocates an AST node, its children, and stored values
void free_expr_node(ExprNode *root);

#endif /* AST_H */

